#[derive(Debug, Clone)]
pub struct BindArgs {
    pub key: PolicyText,
    pub value: PolicyText,
}

pub fn dispatch_bind(
    repo: &mut impl crate::kernel::Repository<Policy>, id: &str, args: BindArgs, mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<Policy> {
        args.key.check_invariants()?;
        args.value.check_invariants()?;
    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, POLICY_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Bind",
        "Bluebook::Policy",
        "Policy",
        "bluebook, name.value",
        &with_references,
        &[

        ],
        None,
        |record| {
        record.with_spec.push(Binding { key: args.key.value.clone(), value: args.value.value.clone() });
            Ok(())
        },
        &[

        ],
        &policy_invariants(),
        &["TriggerBindingAttached"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

impl BindArgs {
    pub fn to_json(&self) -> crate::kernel::Json {
        crate::kernel::Json::Object(
            vec![        ("key".to_string(), self.key.to_json()),
        ("value".to_string(), self.value.to_json()),]
                .into_iter()
                .filter(|(_, v)| !matches!(v, crate::kernel::Json::Null))
                .collect(),
        )
    }
}

impl BindArgs {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
let unknown = v.unknown_keys(&["key", "value", "id", "bluebook", "name"]);
if !unknown.is_empty() {
    return Err(crate::kernel::Refusal::UnknownArgument(format!(
        "Bind does not declare {} — it takes key, value",
        unknown.join(", ")
    )));
}
        Ok(Self {
        key: PolicyText::from_json(&v.require("key", "BindArgs")?.coerce_single_field("value"))?,
        value: PolicyText::from_json(&v.require("value", "BindArgs")?.coerce_single_field("value"))?,
        })
    }
}

